// modules/library/pages/AuthorList.js
import { useEffect, useState } from "react";
import { authorApi } from "../api/authorApi";
import { 
  PencilIcon, 
  TrashIcon, 
  UserPlusIcon,
  ExternalLinkIcon,
  UserIcon,
  GlobeIcon,
  CalendarIcon,
  FlagIcon 
} from "@heroicons/react/24/outline";
import { toast } from "react-hot-toast";

export default function AuthorList() {
  const [authors, setAuthors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [deletingId, setDeletingId] = useState(null);

  useEffect(() => {
    fetchAuthors();
  }, []);

  const fetchAuthors = async () => {
    try {
      setLoading(true);
      const res = await authorApi.get("/");
      setAuthors(res.data);
    } catch (error) {
      toast.error("Failed to load authors");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const deleteAuthor = async (id, name) => {
    if (!window.confirm(`Are you sure you want to delete "${name}"? This action cannot be undone.`)) return;

    try {
      setDeletingId(id);
      await authorApi.delete(`/${id}`);
      setAuthors(authors.filter((a) => a.author_id !== id));
      toast.success("Author deleted successfully");
    } catch (error) {
      toast.error("Failed to delete author");
      console.error(error);
    } finally {
      setDeletingId(null);
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return "-";
    return new Date(dateString).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const truncateText = (text, maxLength = 30) => {
    if (!text) return "-";
    return text.length > maxLength ? `${text.substring(0, maxLength)}...` : text;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-6">
        <div className="max-w-7xl mx-auto">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 rounded w-48 mb-8"></div>
            <div className="h-12 bg-gray-200 rounded w-36 mb-8"></div>
            <div className="space-y-4">
              {[...Array(5)].map((_, i) => (
                <div key={i} className="h-16 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-4 md:p-6 lg:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8">
          <div>
            <h1 className="text-3xl md:text-4xl font-bold text-gray-900 mb-2">
              Authors
            </h1>
            <p className="text-gray-600">
              {authors.length} {authors.length === 1 ? "author" : "authors"} in library
            </p>
          </div>
          
          <a
            href="/library/author/create"
            className="inline-flex items-center justify-center px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-medium rounded-lg shadow-lg hover:shadow-xl transition-all duration-200 mt-4 md:mt-0"
          >
            <UserPlusIcon className="w-5 h-5 mr-2" />
            Add New Author
          </a>
        </div>

        {/* Table Container */}
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-200">
          {/* Table */}
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gradient-to-r from-gray-50 to-gray-100">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                    <div className="flex items-center">
                      <UserIcon className="w-4 h-4 mr-2" />
                      Author
                    </div>
                  </th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                    <div className="flex items-center">
                      <FlagIcon className="w-4 h-4 mr-2" />
                      Nationality
                    </div>
                  </th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                    <div className="flex items-center">
                      <CalendarIcon className="w-4 h-4 mr-2" />
                      Date of Birth
                    </div>
                  </th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                    <div className="flex items-center">
                      <GlobeIcon className="w-4 h-4 mr-2" />
                      Website
                    </div>
                  </th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                    Actions
                  </th>
                </tr>
              </thead>
              
              <tbody className="bg-white divide-y divide-gray-100">
                {authors.length > 0 ? (
                  authors.map((author) => (
                    <tr 
                      key={author.author_id} 
                      className="hover:bg-gray-50 transition-colors duration-150"
                    >
                      {/* Author Info */}
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="flex items-center">
                          <div className="flex-shrink-0 h-10 w-10 bg-gradient-to-br from-blue-100 to-indigo-100 rounded-full flex items-center justify-center mr-4">
                            <span className="text-blue-600 font-semibold">
                              {author.first_name?.[0]}{author.last_name?.[0]}
                            </span>
                          </div>
                          <div>
                            <div className="text-sm font-medium text-gray-900">
                              {author.first_name} {author.last_name}
                            </div>
                            <div className="text-sm text-gray-500">
                              ID: {author.author_id}
                            </div>
                          </div>
                        </div>
                      </td>

                      {/* Nationality */}
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-gray-100 text-gray-800">
                          {author.nationality || "-"}
                        </span>
                      </td>

                      {/* Date of Birth */}
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm text-gray-900">
                          {formatDate(author.date_of_birth)}
                        </div>
                      </td>

                      {/* Website */}
                      <td className="px-6 py-4">
                        {author.website ? (
                          <a
                            href={author.website}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center text-sm text-blue-600 hover:text-blue-800 hover:underline"
                          >
                            {truncateText(author.website)}
                            <ExternalLinkIcon className="w-4 h-4 ml-1" />
                          </a>
                        ) : (
                          <span className="text-sm text-gray-400">-</span>
                        )}
                      </td>

                      {/* Actions */}
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                        <div className="flex items-center space-x-3">
                          <a
                            href={`/library/author/edit/${author.author_id}`}
                            className="inline-flex items-center px-4 py-2 bg-gradient-to-r from-blue-50 to-blue-100 text-blue-700 rounded-lg hover:from-blue-100 hover:to-blue-200 transition-all duration-200 shadow-sm hover:shadow"
                          >
                            <PencilIcon className="w-4 h-4 mr-2" />
                            Edit
                          </a>
                          <button
                            onClick={() => deleteAuthor(author.author_id, `${author.first_name} ${author.last_name}`)}
                            disabled={deletingId === author.author_id}
                            className="inline-flex items-center px-4 py-2 bg-gradient-to-r from-red-50 to-red-100 text-red-700 rounded-lg hover:from-red-100 hover:to-red-200 transition-all duration-200 shadow-sm hover:shadow disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {deletingId === author.author_id ? (
                              <>
                                <div className="w-4 h-4 mr-2 border-2 border-red-700 border-t-transparent rounded-full animate-spin"></div>
                                Deleting...
                              </>
                            ) : (
                              <>
                                <TrashIcon className="w-4 h-4 mr-2" />
                                Delete
                              </>
                            )}
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="px-6 py-12 text-center">
                      <div className="text-gray-400">
                        <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                          <UserIcon className="w-8 h-8 text-gray-300" />
                        </div>
                        <p className="text-lg font-medium text-gray-500 mb-2">
                          No authors found
                        </p>
                        <p className="text-gray-400 mb-6">
                          Get started by adding your first author
                        </p>
                        <a
                          href="/library/author/create"
                          className="inline-flex items-center px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-medium rounded-lg shadow-lg hover:shadow-xl transition-all duration-200"
                        >
                          <UserPlusIcon className="w-5 h-5 mr-2" />
                          Add First Author
                        </a>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          {/* Footer */}
          {authors.length > 0 && (
            <div className="px-6 py-4 bg-gray-50 border-t border-gray-200">
              <div className="flex items-center justify-between">
                <p className="text-sm text-gray-600">
                  Showing <span className="font-medium">{authors.length}</span> authors
                </p>
                <div className="text-sm text-gray-600">
                  Last updated: {new Date().toLocaleDateString()}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
